def merge_ranges(ranges):
    # Filter out empty ranges and sort by start
    non_empty = [r for r in ranges if r[0] < r[1]]
    sorted_ranges = sorted(non_empty, key=lambda x: x[0])
    merged = []
    for r in sorted_ranges:
        if not merged:
            merged.append([r[0], r[1]])
        else:
            last = merged[-1]
            if r[0] <= last[1]:  # overlapping or touching
                last[1] = max(last[1], r[1])
            else:
                merged.append([r[0], r[1]])
    # Convert back to tuples
    return [tuple(interval) for interval in merged]

import heapq
from collections import defaultdict
def topological(edges, nodes):
    adj = defaultdict(list)
    indegree = {node: 0 for node in nodes}
    seen = set()
    for u, v in edges:
        if (u, v) in seen:
            continue
        seen.add((u, v))
        if u not in nodes or v not in nodes:
            # ignore edges with unknown nodes (should not occur per problem constraints)
            continue
        adj[u].append(v)
        indegree[v] += 1
    heap = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(heap)
    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(heap, neighbor)
    if len(result) != len(nodes):
        raise ValueError("Cycle detected")
    return result

def decode_runs(text):
    if text == "":
        return ""
    i = 0
    n = len(text)
    result = []
    while i < n:
        if not text[i].isdigit():
            raise ValueError("Missing count")
        count_start = i
        while i < n and text[i].isdigit():
            i += 1
        count_str = text[count_start:i]
        count = int(count_str)
        if count == 0:
            raise ValueError("Zero count")
        if i >= n or not ('a' <= text[i] <= 'z'):
            raise ValueError("Invalid letter")
        letter = text[i]
        result.append(letter * count)
        i += 1
    return ''.join(result)

from collections import OrderedDict
def lru(capacity, operations):
    cache = OrderedDict()
    results = []
    for op in operations:
        if op[0] == "put":
            key = op[1]
            value = op[2]
            if key in cache:
                cache.move_to_end(key)
            cache[key] = value
            if len(cache) > capacity:
                cache.popitem(last=False)
        elif op[0] == "get":
            key = op[1]
            if key in cache:
                cache.move_to_end(key)
                results.append(cache[key])
            else:
                results.append(-1)
    return results

def flatten(value):
    if isinstance(value, (list, tuple)):
        result = []
        for item in value:
            result.extend(flatten(item))
        return result
    else:
        return [value]

import sys
def path_normalize(path):
    absolute = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if absolute:
                if stack:
                    stack.pop()
            else:
                if stack and stack[-1] != '..':
                    stack.pop()
                else:
                    stack.append('..')
        else:
            stack.append(part)
    if absolute:
        if not stack:
            return "/"
        else:
            return "/" + "/".join(stack)
    else:
        if not stack:
            return "."
        else:
            return "/".join(stack)

import heapq
def shortest(graph, start, end):
    """Return shortest distance from start to end in graph with nonnegative weights."""
    if start == end:
        return 0
    # Dijkstra's algorithm
    dist = {start: 0}
    heap = [(0, start)]
    while heap:
        d, node = heapq.heappop(heap)
        # Skip outdated entries
        if d > dist.get(node, float('inf')):
            continue
        if node == end:
            return d
        for neighbor, weight in graph.get(node, []):
            new_dist = d + weight
            if new_dist < dist.get(neighbor, float('inf')):
                dist[neighbor] = new_dist
                heapq.heappush(heap, (new_dist, neighbor))
    return None

def window_max(values, k):
    if k <= 0:
        raise ValueError("k must be positive")
    n = len(values)
    if k > n:
        return []
    from collections import deque
    dq = deque()  # stores indices of potential maximums
    result = []
    for i in range(n):
        # Remove indices that are out of the current window
        while dq and dq[0] < i - k + 1:
            dq.popleft()
        # Remove indices of elements smaller than the current element
        while dq and values[dq[-1]] < values[i]:
            dq.pop()
        dq.append(i)
        # Append the maximum for the window ending at i
        if i >= k - 1:
            result.append(values[dq[0]])
    return result

from collections import defaultdict, deque
def rate_limit(events, limit, window):
    if limit == 0:
        return [False] * len(events)
    accepted = defaultdict(deque)
    result = []
    for timestamp, key in events:
        dq = accepted[key]
        # Remove timestamps that are outside the window (<= timestamp - window)
        while dq and dq[0] <= timestamp - window:
            dq.popleft()
        if len(dq) < limit:
            dq.append(timestamp)
            result.append(True)
        else:
            result.append(False)
    return result

def json_pointer(value, pointer):
    if pointer == "":
        return value
    # Unescape the pointer: decode ~0 and ~1
    unescaped_chars = []
    i = 0
    n = len(pointer)
    while i < n:
        c = pointer[i]
        if c == '~':
            if i + 1 >= n:
                raise ValueError("Invalid escape")
            next_c = pointer[i + 1]
            if next_c == '0':
                unescaped_chars.append('~')
                i += 2
            elif next_c == '1':
                unescaped_chars.append('/')
                i += 2
            else:
                raise ValueError("Invalid escape")
        else:
            unescaped_chars.append(c)
            i += 1
    unescaped = ''.join(unescaped_chars)

    # Split into segments
    if unescaped.startswith('/'):
        segments = unescaped.split('/')[1:]
    else:
        segments = unescaped.split('/')
    current = value
    for seg in segments:
        if isinstance(current, dict):
            if seg in current:
                current = current[seg]
            else:
                raise ValueError("Missing path")
        elif isinstance(current, list):
            # Validate segment as a canonical decimal index
            if not seg.isdigit():
                raise ValueError("Invalid list index")
            if len(seg) > 1 and seg[0] == '0':
                raise ValueError("Invalid list index leading zero")
            idx = int(seg)
            if idx < 0 or idx >= len(current):
                raise ValueError("Index out of range")
            current = current[idx]
        else:
            raise ValueError("Invalid path")
    return current

def stable_unique(values):
    seen = []
    result = []
    for v in values:
        # Check if v is equal to any previously seen value
        if not any(v == s for s in seen):
            seen.append(v)
            result.append(v)
    return result

def parse_duration(text):
    if not text:
        raise ValueError("Empty input")
    i = 0
    n = len(text)
    segments = []
    order = {'h': 3, 'm': 2, 's': 1}
    while i < n:
        if text[i].isdigit():
            j = i
            while j < n and text[j].isdigit():
                j += 1
            if j == i:
                raise ValueError("Invalid number")
            num = int(text[i:j])
            i = j
            if i < n and text[i] in order:
                unit = text[i]
                i += 1
            else:
                raise ValueError("Missing unit after number")
            segments.append((num, unit))
        elif text[i] in order:
            raise ValueError("Unexpected unit without number")
        else:
            raise ValueError("Invalid character")
    seen = set()
    prev_rank = None
    for num, unit in segments:
        if unit not in order:
            raise ValueError("Invalid unit")
        if unit in seen:
            raise ValueError("Repeated unit")
        seen.add(unit)
        rank = order[unit]
        if prev_rank is not None and rank > prev_rank:
            raise ValueError("Units not in descending order")
        prev_rank = rank
    total = 0
    for num, unit in segments:
        if unit == 'h':
            total += num * 3600
        elif unit == 'm':
            total += num * 60
        elif unit == 's':
            total += num
    return total

def apply_patch(text, edits):
    # Validate edits list
    if not isinstance(edits, list):
        raise ValueError("Edits must be a list")
    # Check each edit tuple
    for edit in edits:
        if not isinstance(edit, (list, tuple)) or len(edit) != 3:
            raise ValueError("Each edit must be a tuple (start, end, replacement)")
        start, end, replacement = edit
        if not isinstance(start, int) or not isinstance(end, int):
            raise ValueError("Start and end must be integers")
        if start < 0 or end < 0:
            raise ValueError("Offsets must be non-negative")
        if start > end:
            raise ValueError("Start must not be greater than end")
        if end > len(text):
            raise ValueError("End offset out of range")
    # Check for duplicate start offsets
    starts = set()
    for start, end, replacement in edits:
        if start in starts:
            raise ValueError("Duplicate start offset")
        starts.add(start)
    # Sort edits by start position
    sorted_edits = sorted(edits, key=lambda x: x[0])
    # Check for overlapping intervals
    prev_end = -1
    for start, end, replacement in sorted_edits:
        if prev_end > start:
            raise ValueError("Overlapping edits")
        prev_end = end
    # Apply the edits to the original text
    result = []
    last_end = 0
    for start, end, replacement in sorted_edits:
        result.append(text[last_end:start])
        result.append(str(replacement))  # ensure replacement is string
        last_end = end
    result.append(text[last_end:])
    return ''.join(result)

def paginate(items, after, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    # Filter items based on after cursor
    if after is None:
        filtered = items
    else:
        filtered = [item for item in items if item['id'] > after]
    # Sort by id
    filtered.sort(key=lambda x: x['id'])
    # Take the first 'limit' items as the page
    page = filtered[:limit]
    # Determine next cursor
    if len(page) == limit and len(filtered) > limit:
        next_cursor = page[-1]['id']
    else:
        next_cursor = None
    return page, next_cursor

def retry_delays(attempts, initial, cap):
    if attempts < 0 or initial < 0 or cap < 0:
        raise ValueError("Negative arguments are not allowed")
    delays = []
    for i in range(attempts):
        delay = initial * (2 ** i)
        if delay > cap:
            delay = cap
        delays.append(delay)
    return delays

import csv
import io
def csv_records(text):
    if not text.strip():
        return []
    reader = csv.reader(io.StringIO(text))
    rows = list(reader)
    if not rows:
        return []
    headers = rows[0]
    if len(headers) != len(set(headers)):
        raise ValueError("Duplicate headers")
    result = []
    for row in rows[1:]:
        if len(row) != len(headers):
            raise ValueError("Row has different number of fields")
        result.append(dict(zip(headers, row)))
    return result

def version_sort(versions):
    def key_func(version):
        # Split into integer parts
        parts = version.split('.')
        nums = [int(p) for p in parts]
        # Remove trailing zero segments
        while nums and nums[-1] == 0:
            nums.pop()
        return nums
    # Python's sort is stable, so ties retain original order
    return sorted(versions, key=key_func)

def glob_match(pattern, text):
    from functools import lru_cache
    @lru_cache(None)
    def dp(i, j):
        if i == len(pattern):
            return j == len(text)
        if j == len(text):
            # remaining pattern must be all '*'
            for k in range(i, len(pattern)):
                if pattern[k] != '*':
                    return False
            return True
        p = pattern[i]
        t = text[j]
        if p == '*':
            return dp(i+1, j) or dp(i, j+1)
        elif p == '?':
            return dp(i+1, j+1)
        elif p == t:
            return dp(i+1, j+1)
        else:
            return False
    return dp(0, 0)

def memo_cycle(definitions, name):
    memo = {}
    visiting = set()
    def compute(n):
        if n not in definitions:
            raise ValueError(f"Missing dependency {n}")
        if n in visiting:
            raise ValueError("Cycle detected")
        if n in memo:
            return memo[n]
        visiting.add(n)
        try:
            val = definitions[n]
            if isinstance(val, int):
                result = val
            elif isinstance(val, list):
                result = 0
                for dep in val:
                    result += compute(dep)
            else:
                raise ValueError(f"Invalid definition for {n}")
            memo[n] = result
            return result
        finally:
            visiting.remove(n)
    return compute(name)
